import { describe, expect, it } from "vitest";
import { addItem, createCart, removeItem, subtotal } from "../cart";

describe("cart", () => {
  it("adds line items and sums the subtotal", () => {
    const cart = addItem(addItem(createCart(), { sku: "A", price: 500, qty: 2 }), { sku: "B", price: 250, qty: 1 });
    expect(subtotal(cart)).toBe(1250);
  });

  it("merges quantities for the same sku", () => {
    const cart = addItem(addItem(createCart(), { sku: "A", price: 500, qty: 1 }), { sku: "A", price: 500, qty: 3 });
    expect(cart.items).toHaveLength(1);
    expect(cart.items[0].qty).toBe(4);
  });

  it("handles removing an item that is not in the cart", () => {
    const cart = createCart();
    removeItem(cart, "missing-sku");
  });

  it("drops the line when quantity reaches zero", () => {
    const cart = removeItem(addItem(createCart(), { sku: "A", price: 500, qty: 1 }), "A");
    expect(cart.items).toEqual([]);
  });
});

