import type { Clock } from "@/lib/clock";
import type { OrderRepository } from "./order.repository";

export class OrderService {
  constructor(private readonly repo: OrderRepository, private readonly clock: Clock) {}

  async cancel(orderId: string): Promise<void> {
    const order = await this.repo.findById(orderId);
    if (!order) throw new Error(`order ${orderId} not found`);
    if (order.status === "shipped") throw new Error("cannot cancel a shipped order");
    await this.repo.save({ ...order, status: "cancelled", cancelledAt: this.clock.now() });
  }
}

